static int64_t z_t4231_find(const z_t4231_t* _this, const z_t61_t* _key, uint64_t _hash, int64_t* _slot_out);
static int64_t z_t4231_find(const z_t4231_t* _this, const z_t61_t* _key, uint64_t _hash, int64_t* _slot_out) {
    if (_this->capacity == 0) return -1;
    uint64_t probe = _hash & (_this->capacity - 1);
    for (uint64_t i = 0; i < _this->capacity; i++) {
        int64_t slot = _this->indices[probe];
        if (slot == Z_T4231_INDEX_EMPTY) {
            if (_slot_out) *_slot_out = (int64_t)probe;
            return -1;
        }
        if (slot != Z_T4231_INDEX_DELETED) {
            if (_this->entries[slot].hash == _hash && z_t4231_keys_equal(&_this->entries[slot].key, _key)) {
                if (_slot_out) *_slot_out = (int64_t)probe;
                return slot;
            }
        }
        probe = (probe + 1) & (_this->capacity - 1);
    }
    return -1;
}

