static z_t10239_t z_t81_parseI64(const z_t81_t* self);
static z_t10239_t z_t81_parseI64(const z_t81_t* self) {
    z_t10239_t out = {0};
    uint64_t i = 0;
    int neg = 0;
    if (self->size == 0) goto empty;
    if (self->data[i] == '+' || self->data[i] == '-') {
        if (self->data[i] == '-') neg = 1;
        i++;
    }
    if (i >= self->size) goto empty;
    uint64_t acc = 0;
    for (; i < self->size; i++) {
        unsigned char c = (unsigned char)self->data[i];
        if (c < '0' || c > '9') goto invalid;
        uint64_t d = (uint64_t)(c - '0');
        if (acc > (UINT64_MAX - d) / 10) goto overflow;
        acc = acc * 10 + d;
    }
    /* range check: fits in i64 */
    uint64_t bound = neg ? (uint64_t)1 << 63 : ((uint64_t)1 << 63) - 1;
    if (acc > bound) goto overflow;
    int64_t v = neg ? -(int64_t)acc : (int64_t)acc;
    if (neg && acc == ((uint64_t)1 << 63)) v = INT64_MIN;
    out.tag = Z_T10239_TAG_1;
    out.data.a1 = v;
    return out;
empty:
    out.tag = Z_T10239_TAG_0;
    out.data.a0 = Z_T9913_TAG_0;
    return out;
invalid:
    out.tag = Z_T10239_TAG_0;
    out.data.a0 = Z_T9913_TAG_1;
    return out;
overflow:
    out.tag = Z_T10239_TAG_0;
    out.data.a0 = Z_T9913_TAG_2;
    return out;
}


static z_t10434_t z_t81_parseU64(const z_t81_t* self);
